text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "一组与三组团队响应分钟中位数排名",
      "business_question": "计算一组与三组各团队的响应分钟中位数，并按升序排名。",
      "priority": "P0",
      "priority_reason": "删除此任务将完全无法回答核心业务问题（一组与三组的响应效率对比），属于最高优先级。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "response_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "response_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
